"Это DWG — закрытый формат AutoCAD, прочитать его напрямую нельзя. Откройте чертёж в AutoCAD или nanoCAD и сохраните как DXF («Сохранить как» → DXF), затем загрузите сюда":"This is DWG — a proprietary AutoCAD format that cannot be read directly. Open the drawing in AutoCAD or nanoCAD and save it as DXF (\"Save as\" → DXF), then upload it here",
"Это пример: дом {n} × {n} м. Поправьте стены на плане и посмотрите вкладки «{n}D» и «Объёмы»":"This is a sample: a {n} × {n} m house. Adjust the walls on the plan and look at the \"{n}D\" and \"Volumes\" tabs",
