"Модель в натуральную величину":"Full-size model",
"На iPhone и iPad здание открывается в «Быстром просмотре»: на экране — то, что видит камера, и модель в настоящую величину. Она стоит на месте: к ней можно подойти и обойти вокруг. Пальцами её можно подвинуть, повернуть и уменьшить":"On iPhone and iPad the building opens in \"Quick Look\": the screen shows what the camera sees and the model at actual size. It stays in place: you can walk up to it and around it. Use your fingers to move, rotate and shrink it",
"на сервере":"on the server",
"На экране — то, что видит камера, и поверх него здание в настоящую величину. Оно стоит на месте: к нему можно подойти, обойти вокруг и зайти внутрь через дверные проёмы":"The screen shows what the camera sees with the building at actual size on top. It stays in place: you can walk up to it, around it and inside through the door openings",
"На экране будет то, что видит камера, и поверх него — модель. Её можно подвинуть и повернуть пальцами, отключить слои и сделать снимок":"The screen will show what the camera sees with the model on top. You can move and rotate it with your fingers, turn off layers and take a snapshot",
