", раскрытие не измерено — линия трещины не выделилась":", opening not measured — the crack line could not be isolated",
", раскрытие не определено: линия тоньше {n} пикселей фото — укажите ширину участка или снимите ближе, класс может оказаться выше":", opening not determined: the line is thinner than {n} pixels of the photo — specify the width of the area or shoot closer; the class may turn out higher",
"Белый налёт — соли, которые выносит вода, проходящая сквозь конструкцию: признак протечки или намокания":"White deposit — salts carried out by water passing through the structure: a sign of a leak or wetting",
"Бетон откалывается от удара, промерзания во влажном состоянии или давления ржавеющей арматуры":"Concrete spalls from impact, freezing while wet, or the pressure of rusting reinforcement",
"Вскрыть участок, зачистить металл до чистого, обработать преобразователем ржавчины и восстановить защитный слой ремонтным составом":"Open up the area, clean the metal to a bright surface, treat with a rust converter and restore the cover with a repair compound",
"Вырезать повреждённый участок по ровному контуру, очистить, обработать битумной эмульсией и заделать асфальтобетонной смесью с уплотнением":"Cut out the damaged area along a straight outline, clean it, treat with bitumen emulsion and patch with an asphalt mix with compaction",
"Глубокий разлом / силовая трещина бетона":"Deep fracture / structural crack in concrete",
"Для несущих элементов сверить размер и число сучков с сортом древесины по проекту; выпавшие сучки — заделать, ослабленный элемент — усилить или заменить":"For load-bearing elements, check the size and number of knots against the timber grade in the design; fill loose knots, strengthen or replace a weakened element",
"Зачистить арматуру, оценить потерю сечения (при заметной — нужен расчёт и усиление), обработать антикоррозийным составом и восстановить защитный слой":"Clean the reinforcement, assess the loss of cross-section (if noticeable, calculation and strengthening are needed), treat with an anti-corrosion compound and restore the cover",
"Зачистить и закрасить или зашлифовать; на металле — загрунтовать антикоррозийным составом":"Clean and paint over or sand; on metal — prime with an anti-corrosion compound",
"Защитный слой бетона разрушен, арматура открыта влаге и воздуху и теряет сечение":"The concrete cover is destroyed; the reinforcement is exposed to moisture and air and is losing cross-section",
"Конструктивная трещина с раскрытием":"Structural crack with an opening",
"Коррозия / ржавые потёки":"Corrosion / rust streaks",
"Краска, штукатурка или плитка отстают от основания — обычно из-за влаги или слабого сцепления":"Paint, plaster or tiles are coming away from the base — usually because of moisture or poor adhesion",
"Механическое повреждение поверхности; на металле через царапину начинается коррозия":"Mechanical damage to the surface; on metal, corrosion starts through a scratch",
"Найти и устранить источник влаги, очистить поверхность, после просушки обработать гидрофобизатором":"Find and eliminate the source of moisture, clean the surface and, after drying, treat with a water repellent",
"Найти и устранить источник воды, просушить конструкцию, затем восстановить отделку":"Find and eliminate the source of water, dry the structure, then restore the finish",
"Оценить, несущий ли элемент: несущий — показать инженеру, остальное — выправить или заменить и восстановить покрытие":"Assess whether the element is load-bearing: if so — show it to an engineer; otherwise — straighten or replace it and restore the coating",
"Плесень растёт там, где конструкция постоянно влажная и плохо проветривается":"Mould grows where the structure is constantly damp and poorly ventilated",
"Покрытие разрушено до основания: вода, морозы и нагрузка от колёс выбивают ослабленный участок":"The surfacing is destroyed down to the base: water, frost and wheel loads knock out the weakened area",
"Ржавчина выходит на поверхность, когда корродирует арматура или закладные детали под защитным слоем":"Rust comes to the surface when reinforcement or embedded parts corrode under the cover",
"Скол / разрушение бетона":"Spalling / concrete failure",
"След удара или перегрузки: на металле и пластике вмятина ослабляет элемент и повреждает покрытие":"A mark of impact or overload: on metal and plastic a dent weakens the element and damages the coating",
"Снять отслоившийся слой до прочного, выяснить и устранить причину увлажнения, загрунтовать и восстановить отделку":"Remove the delaminated layer down to a sound one, find and eliminate the cause of dampness, prime and restore the finish",
"Сучок (порок древесины)":"Knot (timber defect)",
"Сучок ослабляет сечение деревянного элемента; выпадающие сучки и сучки с трещиной хуже здоровых":"A knot weakens the cross-section of a timber element; loose knots and knots with a crack are worse than sound ones",
"Тёмное или жёлтое пятно — след воды: протекает кровля, труба или шов":"A dark or yellow stain is a trace of water: the roof, a pipe or a joint is leaking",
"Удалить слабый бетон до прочного, обеспылить, загрунтовать и восстановить сечение ремонтной смесью; при глубине до арматуры — сначала защитить арматуру":"Remove weak concrete down to sound material, dust off, prime and restore the cross-section with a repair mix; if it reaches the reinforcement — protect the reinforcement first",
"Усадочная трещина штукатурного слоя / скол":"Shrinkage crack in the plaster layer / chip",
"Устранить источник влаги и наладить вентиляцию, удалить поражённую отделку, обработать антисептиком и восстановить":"Eliminate the source of moisture and set up ventilation, remove the affected finish, treat with an antiseptic and restore",
