"Аварийное — опасность обрушения или разрушения элемента; ограничить эксплуатацию до обследования":"Emergency — risk of collapse or failure of the element; restrict use until surveyed",
"Волосяные трещины в пределах допуска: расшить и затереть ремонтным составом при ближайшей отделке; при появлении новых трещин — поставить маяки":"Hairline cracks within tolerance: rout and fill with a repair compound at the next finishing; if new cracks appear — install tell-tales",
"Высокий: арматура оголена или корродирует — сечение теряется, нужен осмотр и защита":"High: the reinforcement is exposed or corroding — cross-section is being lost, inspection and protection are needed",
"Высокий: через раскрытую трещину вода и соли попадают прямо к арматуре — коррозия идёт быстро":"High: through an open crack water and salts reach the reinforcement directly — corrosion is fast",
"ГОСТ {n} «Правила обследования и мониторинга технического состояния»; СП РК EN {n}-{n}-{n}:{n}/{n}, п. {n} — ограничение раскрытия трещин (обычно до {n} мм)":"GOST {n} \"Rules for inspection and monitoring of technical condition\"; SP RK EN {n}-{n}-{n}:{n}/{n}, cl. {n} — crack width limitation (usually up to {n} mm)",
