"ИИ-модель не увидела на снимке дефектов. Если дефект есть — снимите ближе и при хорошем свете или отметьте его на фото вручную":"The AI model saw no defects in the picture. If there is a defect — shoot closer and in good light, or mark it on the photo manually",
"Низкий: раскрытие в пределах допустимого":"Low: opening within the permissible range",
