"Повышенный: раскрытие больше {n} мм — влага доходит до арматуры":"Elevated: opening over {n} mm — moisture reaches the reinforcement",
"работоспособное":"serviceable",
"Работоспособное — нужен ремонт, чтобы влага не проникала к арматуре":"Serviceable — repair is needed so that moisture does not reach the reinforcement",
"Расшивка и затирка волосяных трещин ремонтным составом":"Routing and filling of hairline cracks with a repair compound",
"Расшивка и инъектирование трещин под давлением":"Routing and pressure injection of cracks",
"Расшить трещину и заполнить её низковязким эпоксидным составом (инъектирование), затем восстановить защитный слой ремонтной смесью, чтобы влага не попадала к арматуре":"Rout the crack and fill it with a low-viscosity epoxy compound (injection), then restore the cover with a repair mix so that moisture does not reach the reinforcement",
"Срочно вызвать специализированную организацию для обследования по ГОСТ {n} и выяснить причину (осадка, перегрузка, промерзание, удар). До решения — оградить место и ограничить нагрузку. Сборный элемент (кольцо колодца, плиту, перемычку) с раскрытой трещиной, как правило, заменяют или усиливают обоймой; инъектирование — только как временная мера":"Urgently call a specialized organization for a survey under GOST {n} and find the cause (settlement, overload, freezing, impact). Until a decision is made — fence off the area and limit the load. A precast element (manhole ring, slab, lintel) with an open crack is usually replaced or strengthened with a jacket; injection is only a temporary measure",
"Умеренный: раскрытие больше допустимых {n} мм — со временем возможна коррозия":"Moderate: opening over the permissible {n} mm — corrosion is possible over time",
"Установить маяки и {n}–{n} недели наблюдать, растёт ли раскрытие. Если трещина не растёт — расшить, инъектировать эпоксидным составом под давлением через пакеры и восстановить защитный слой. Если растёт — нужно обследование и усиление конструкции":"Install tell-tales and watch for {n}–{n} weeks whether the opening grows. If the crack does not grow — rout it, inject an epoxy compound under pressure through packers and restore the cover. If it grows — a survey and strengthening of the structure are needed",
"Установка маяков и наблюдение за раскрытием ({n}–{n} недели)":"Installing tell-tales and monitoring the opening ({n}–{n} weeks)",
