"Другим пользователям — в пределах заказа: исполнитель видит контакты заказчика по заказу, на который откликнулся, заказчик — контакты исполнителя. Анкета исполнителя и объявления о технике видны всем пользователям":"To other users — within an order: the contractor sees the contacts of the client for the order they responded to, and the client sees the contractor's contacts. The contractor profile and equipment listings are visible to all users",
