"Сервис — площадка, где заказчики и исполнители находят друг друга. Договор подряда, поставки или аренды техники заключается между пользователями; Оператор не является его стороной, если прямо не указано иное":"The Service is a platform where clients and contractors find each other. A contract for works, supply or equipment rental is concluded between users; the Operator is not a party to it unless expressly stated otherwise",
