"Сметы, расчёты объёмов и заключения о дефектах, которые формирует Сервис, — предварительные и справочные. Они основаны на нормативах, технологических картах и рыночных ценах на дату расчёта и не являются проектной документацией, заключением экспертизы или публичной офертой. Окончательные объём и стоимость работ определяют заказчик и исполнитель в своём договоре":"Estimates, quantity calculations and defect conclusions generated by the Service are preliminary and for reference. They are based on standards, process charts and market prices as of the calculation date and are not design documentation, an expert opinion or a public offer. The final scope and cost of works are determined by the client and the contractor in their contract",
