"Модель могла что-то пропустить или отметить лишнее: выберите вид дефекта и обведите его на фото. Трещина будет измерена и попадёт в заключение; лишнюю зону можно убрать в списке ниже":"The model may have missed something or marked too much: choose the defect type and outline it on the photo. A crack will be measured and included in the report; an extra zone can be removed in the list below",
"Модель обучена на трещинах; коррозия и сколы — по осмотру инженера":"The model is trained on cracks; corrosion and spalling are assessed by an engineer's inspection",
"неизвестная ошибка":"unknown error",
"Расширенное распознавание ИИ-моделью зрения сейчас недоступно. Работает анализ на устройстве: он находит трещины, сколы, оголённую арматуру, высолы, ржавчину, пятна, выбоины, отслоение отделки, плесень, сучки, царапины и вмятины; часть дефектов пропускает (хуже всего видит плесень, ржавчину, выбоины и дефекты на плитке и стекле) и может принять за трещину шов, край или тень. Пропущенное отметьте на фото вручную, лишнее уберите":"Extended recognition by the AI vision model is unavailable right now. On-device analysis is working: it finds cracks, spalling, exposed reinforcement, efflorescence, rust, stains, potholes, peeling finish, mould, knots, scratches and dents; it misses some defects (it is worst at mould, rust, potholes and defects on tiles and glass) and may mistake a joint, edge or shadow for a crack. Mark what was missed on the photo manually and remove what is extra",
